import express from "express";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, "data", "books.json");
const PORT = process.env.PORT || 3000;

const app = express();

app.use(express.urlencoded({ extended: true }));
app.use(express.json());

function loadBooks() {
  try {
    if (!fs.existsSync(DATA_FILE)) return [];
    const raw = fs.readFileSync(DATA_FILE, "utf-8");
    if (!raw.trim()) return [];
    return JSON.parse(raw);
  } catch {
    return [];
  }
}

function saveBooks(books) {
  fs.mkdirSync(path.dirname(DATA_FILE), { recursive: true });
  fs.writeFileSync(DATA_FILE, JSON.stringify(books, null, 2));
}

function escapeHtml(s) {
  return String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: system-ui, -apple-system, sans-serif; max-width: 800px; margin: 0 auto; padding: 2rem 1rem; background: #fafaf8; color: #1a1a1a; line-height: 1.5; }
h1 { font-size: 1.8rem; margin-bottom: 0.25rem; }
.subtitle { color: #666; margin-bottom: 2rem; }
h2 { font-size: 1.2rem; margin: 1.5rem 0 0.75rem; border-bottom: 1px solid #ddd; padding-bottom: 0.4rem; }
.book-list { list-style: none; display: grid; gap: 0.75rem; }
.book-card { background: white; border: 1px solid #e5e5e5; border-radius: 8px; padding: 1rem; display: flex; justify-content: space-between; align-items: center; gap: 1rem; }
.book-card a { text-decoration: none; color: #1a1a1a; }
.book-card a:hover { text-decoration: underline; }
.book-title { font-weight: 600; }
.book-author { color: #666; font-size: 0.9rem; }
.badge { font-size: 0.75rem; padding: 0.2rem 0.5rem; border-radius: 999px; background: #eee; white-space: nowrap; }
.badge.finished { background: #d1fae5; color: #065f46; }
.badge.reading { background: #dbeafe; color: #1e40af; }
.empty { color: #888; font-style: italic; padding: 0.5rem 0; }
form.add-form { background: white; border: 1px solid #e5e5e5; border-radius: 8px; padding: 1.2rem; margin: 1.5rem 0; display: grid; gap: 0.75rem; }
form.add-form label { font-size: 0.85rem; font-weight: 600; display: grid; gap: 0.25rem; }
input, textarea { padding: 0.5rem 0.7rem; border: 1px solid #ccc; border-radius: 6px; font: inherit; }
textarea { resize: vertical; }
button, .btn { background: #111; color: white; border: none; padding: 0.55rem 1rem; border-radius: 6px; cursor: pointer; font: inherit; font-size: 0.9rem; text-decoration: none; display: inline-block; }
button:hover, .btn:hover { background: #333; }
button.secondary { background: white; color: #111; border: 1px solid #ccc; }
button.secondary:hover { background: #f5f5f5; }
.btn-finish { background: #059669; }
.btn-finish:hover { background: #047857; }
.detail { background: white; border: 1px solid #e5e5e5; border-radius: 8px; padding: 1.5rem; margin-top: 1rem; }
.detail h1 { margin-bottom: 0.2rem; }
.share { margin-top: 1rem; font-size: 0.85rem; color: #666; }
.share input { width: 100%; margin-top: 0.3rem; font-size: 0.85rem; background: #f9f9f9; }
.actions { margin-top: 1rem; display: flex; gap: 0.5rem; flex-wrap: wrap; }
nav a { color: #111; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function renderHome(books) {
  const reading = books.filter(b => b.status !== "finished");
  const finished = books.filter(b => b.status === "finished");

  const list = (items, emptyMsg) => {
    if (items.length === 0) return `<p class="empty">${emptyMsg}</p>`;
    return `<ul class="book-list">` + items.map(b => `
      <li class="book-card">
        <div>
          <a href="/books/${escapeHtml(b.id)}" class="book-title">${escapeHtml(b.title)}</a>
          <div class="book-author">by ${escapeHtml(b.author || "Unknown")}</div>
        </div>
        <div style="display:flex;gap:0.5rem;align-items:center">
          <span class="badge ${b.status === 'finished' ? 'finished' : 'reading'}">${b.status === 'finished' ? 'Finished' : 'Reading'}</span>
          ${b.status !== 'finished' ? `<form method="POST" action="/books/${escapeHtml(b.id)}/finish" style="margin:0"><button class="btn-finish" type="submit">Mark finished</button></form>` : ``}
        </div>
      </li>
    `).join("") + `</ul>`;
  };

  const body = `
<nav><a href="/">📚 My Books</a></nav>
<h1 style="margin-top:1rem">My Books</h1>
<p class="subtitle">Track what you're reading and what you've finished.</p>

<h2>Currently Reading</h2>
${list(reading, "No books currently reading. Add one below!")}

<h2>Finished</h2>
${list(finished, "No finished books yet.")}

<h2>Add a Book</h2>
<form class="add-form" method="POST" action="/books">
  <label>Title * <input name="title" required placeholder="The Great Gatsby"></label>
  <label>Author <input name="author" placeholder="F. Scott Fitzgerald"></label>
  <label>Notes <textarea name="notes" rows="3" placeholder="Your thoughts, quotes, etc."></textarea></label>
  <div><button type="submit">Add book</button></div>
</form>
`;
  return layout("My Books", body);
}

function renderDetail(book, req) {
  const shareUrl = `${req.protocol}://${req.get("host")}/books/${book.id}`;
  const body = `
<nav><a href="/">← Back to My Books</a></nav>
<div class="detail">
  <span class="badge ${book.status === 'finished' ? 'finished' : 'reading'}">${book.status === 'finished' ? 'Finished' : 'Reading'}</span>
  <h1 style="margin-top:0.5rem">${escapeHtml(book.title)}</h1>
  <p class="book-author" style="font-size:1rem">by ${escapeHtml(book.author || "Unknown")}</p>
  ${book.notes ? `<div style="margin-top:1rem"><strong>Notes</strong><p style="white-space:pre-wrap;margin-top:0.25rem">${escapeHtml(book.notes)}</p></div>` : `<p style="margin-top:1rem;color:#888"><em>No notes yet.</em></p>`}
  <div class="actions">
    ${book.status !== 'finished' ? `<form method="POST" action="/books/${escapeHtml(book.id)}/finish"><button class="btn-finish" type="submit">Mark as finished</button></form>` : ``}
    <a class="btn secondary" href="/">Back to list</a>
  </div>
  <div class="share">
    <label>Shareable link:
      <input readonly value="${escapeHtml(shareUrl)}" onclick="this.select()">
    </label>
  </div>
</div>
`;
  return layout(book.title, body);
}

app.get("/", (req, res) => {
  const books = loadBooks();
  res.send(renderHome(books));
});

app.get("/books/:id", (req, res) => {
  const books = loadBooks();
  const book = books.find(b => String(b.id) === String(req.params.id));
  if (!book) return res.status(404).send(layout("Not found", `<nav><a href="/">← Back</a></nav><h1>Book not found</h1><p>No book with id ${escapeHtml(req.params.id)}</p>`));
  res.send(renderDetail(book, req));
});

app.post("/books", (req, res) => {
  const { title, author, notes } = req.body;
  if (!title || !String(title).trim()) {
    return res.status(400).send(layout("Error", `<p>Title is required.</p><a href="/">Go back</a>`));
  }
  const books = loadBooks();
  const book = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    title: String(title).trim(),
    author: String(author || "").trim(),
    notes: String(notes || "").trim(),
    status: "reading",
    createdAt: new Date().toISOString()
  };
  books.push(book);
  saveBooks(books);
  const wantsJson = req.headers.accept?.includes("application/json") || req.headers["content-type"]?.includes("application/json");
  if (wantsJson && req.headers.accept?.includes("application/json")) {
    return res.status(201).json(book);
  }
  res.redirect("/");
});

app.post("/books/:id/finish", (req, res) => {
  const books = loadBooks();
  const book = books.find(b => String(b.id) === String(req.params.id));
  if (!book) {
    const wantsJson = req.headers.accept?.includes("application/json");
    if (wantsJson) return res.status(404).json({ error: "Not found" });
