  }
  book.status = "finished";
  saveBooks(books);
  const wantsJson = req.headers.accept?.includes("application/json");
  if (wantsJson) return res.json(book);
  const referer = req.get("referer") || "/";
  res.redirect(referer.includes(`/books/${book.id}`) ? `/books/${book.id}` : "/");
});

app.get("/api/books", (req, res) => {
  res.json(loadBooks());
});

app.get("/api/books/:id", (req, res) => {
  const books = loadBooks();
  const book = books.find(b => String(b.id) === String(req.params.id));
  if (!book) return res.status(404).json({ error: "Not found" });
  res.json(book);
});

app.use((req, res) => {
  res.status(404).send(layout("Not found", `<nav><a href="/">← Back</a></nav><h1>Page not found</h1>`));
});

if (process.env.NODE_ENV !== "test") {
  app.listen(PORT, () => console.log(`Listening on http://localhost:${PORT}`));
}

export default app;
